 *     printer.printRecord("id", "userName", "firstName", "lastName", "birthday");

 *     printer.printRecord(1, "john73", "John", "Doe", LocalDate.of(1973, 9, 15));

 *     printer.println();

 *     printer.printRecord(2, "mary", "Mary", "Meyer", LocalDate.of(1985, 3, 29));

 * } catch (IOException ex) {

