        try {

            try (IOStream<String> stream = IOStream.of(format.builder().setHeader(resultSet).get().getHeader())) {

                stream.forEachOrdered(this::print);

            }

            println();

        } finally {

            lock.unlock();

        }

    }



    /**

     * Prints the record separator.

