    /**

     * Tests whether a given column is mapped, that is, its name has been defined to the parser.

     *

     * @param name

     *            the name of the column to be retrieved.

     * @return whether a given column is mapped.

     */

    public boolean isMapped(final String name) {

        final Map<String, Integer> headerMap = getHeaderMapRaw();

        return name != null && headerMap != null && headerMap.containsKey(name);

    }



    /**

     * Tests whether a column with a given index has a value.

     *

     * @param index

     *         a column index (0-based).

     * @return whether a column with a given index has a value.

     */

    public boolean isSet(final int index) {

        return 0 <= index && index < values.length;

    }



    /**

     * Tests whether a given column is mapped and has a value.

     *

     * @param name

     *            the name of the column to be retrieved.

     * @return whether a given column is mapped and has a value.

